import net.runelite.client.util.QuantityFormatter;

public final class VorkathPanel extends PluginPanel
{
	private static final Color ACCENT = new Color(100, 160, 255);   // icy-blue to suit Vorkath
	private static final Color MUTED = ColorScheme.LIGHT_GRAY_COLOR;

	private final SessionTracker session;
	private final Client client;
	private final ItemManager itemManager;

	private final JLabel status       = value();
	private final JLabel sessionTime  = value();
	private final JLabel instanceTime = value();
	private final JLabel idleTime     = value();
	private final JLabel kills        = value();
	private final JLabel deaths       = value();
	private final JLabel xp           = value();
	private final JLabel xpHour       = value();
	private final JLabel gpGained     = value();
	private final JLabel gpSpent      = value();
	private final JLabel netGp        = value();
	private final JLabel gpHour       = value();

	private final JLabel dropsTitle      = new JLabel("Vorkath x 0");
	private final JLabel dropsTotalValue = new JLabel("0 gp");
	private final JPanel dropsGridPanel  = new JPanel();
	private Map<Integer, Integer> lastRenderedItems = new LinkedHashMap<>();

	private final JLabel resourcesTitle      = new JLabel("Resources used");
	private final JLabel resourcesTotalValue = new JLabel("0 gp");
	private final JPanel resourcesGridPanel  = new JPanel();
	private List<SessionTracker.ResourceUse> lastRenderedResources = new ArrayList<>();

	public VorkathPanel(SessionTracker session, Client client, ItemManager itemManager)
	{
		super(false);
		this.session = session;
		this.client = client;
		this.itemManager = itemManager;

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel content = new JPanel();
		content.setOpaque(false);
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBorder(new EmptyBorder(10, 10, 10, 10));

		// ── Header ──────────────────────────────────────────────
		JPanel header = new JPanel(new BorderLayout());
		header.setOpaque(false);
		JLabel title = new JLabel("VORKATH PROFIT TRACKER");
		title.setForeground(ACCENT);
		title.setFont(FontManager.getRunescapeBoldFont());
		header.add(title, BorderLayout.WEST);
		header.add(status, BorderLayout.EAST);
		content.add(header);
		content.add(Box.createVerticalStrut(10));

		// ── Stats card ──────────────────────────────────────────
		JPanel card = new JPanel();
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(new EmptyBorder(8, 10, 8, 10));
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));

		section(card, "SESSION");
		row(card, "Session time", sessionTime);
		row(card, "Instance time", instanceTime);
		row(card, "Idle time", idleTime);
		card.add(Box.createVerticalStrut(6));
		row(card, "Kills", kills);
		row(card, "Deaths", deaths);
		card.add(Box.createVerticalStrut(6));
		row(card, "XP gained", xp);
		row(card, "XP / hour", xpHour);
		card.add(Box.createVerticalStrut(6));
		row(card, "GP gained", gpGained);
		row(card, "GP spent", gpSpent);
		row(card, "Net profit", netGp);
		row(card, "Net GP / hour", gpHour);

		content.add(card);
		content.add(Box.createVerticalStrut(10));

		// ── Drops section ───────────────────────────────────────
		JPanel dropsCard = new JPanel(new BorderLayout());
		dropsCard.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		dropsCard.setBorder(new EmptyBorder(0, 0, 0, 0));

		JPanel dropsHeader = new JPanel(new BorderLayout());
		dropsHeader.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		dropsHeader.setBorder(new EmptyBorder(6, 8, 6, 8));

		dropsTitle.setForeground(Color.WHITE);
		dropsTitle.setFont(FontManager.getRunescapeBoldFont());
		dropsHeader.add(dropsTitle, BorderLayout.WEST);

		dropsTotalValue.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		dropsTotalValue.setFont(FontManager.getRunescapeSmallFont());
		dropsHeader.add(dropsTotalValue, BorderLayout.EAST);

		dropsCard.add(dropsHeader, BorderLayout.NORTH);

		dropsGridPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		dropsCard.add(dropsGridPanel, BorderLayout.CENTER);

		content.add(dropsCard);
		content.add(Box.createVerticalStrut(10));

		// ── Resources used section (ammo, runes, supplies, teleports, scales) ─
		JPanel resourcesCard = new JPanel(new BorderLayout());
		resourcesCard.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		JPanel resourcesHeader = new JPanel(new BorderLayout());
		resourcesHeader.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		resourcesHeader.setBorder(new EmptyBorder(6, 8, 6, 8));

		resourcesTitle.setForeground(Color.WHITE);
		resourcesTitle.setFont(FontManager.getRunescapeBoldFont());
		resourcesHeader.add(resourcesTitle, BorderLayout.WEST);

		resourcesTotalValue.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		resourcesTotalValue.setFont(FontManager.getRunescapeSmallFont());
		resourcesHeader.add(resourcesTotalValue, BorderLayout.EAST);

		resourcesCard.add(resourcesHeader, BorderLayout.NORTH);

		resourcesGridPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		resourcesCard.add(resourcesGridPanel, BorderLayout.CENTER);

		content.add(resourcesCard);
		content.add(Box.createVerticalStrut(10));

		// ── Reset button ────────────────────────────────────────
		JButton resetButton = new JButton("Reset Session");
		resetButton.setToolTipText("Clear kills, deaths, timers, XP and GP totals for a new session");
		resetButton.addActionListener(e -> {
			int choice = JOptionPane.showConfirmDialog(this,
				"Reset all Vorkath Profit Tracker session statistics?", "Reset Session",
				JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
			if (choice == JOptionPane.YES_OPTION)
			{
				session.resetSession(System.currentTimeMillis(), combatExperience());
				refresh();
			}
		});
		resetButton.setAlignmentX(LEFT_ALIGNMENT);
		content.add(resetButton);

		// Wrapper & scroll pane for smooth vertical scrolling
		JPanel wrapper = new JPanel(new BorderLayout());
		wrapper.setOpaque(false);
		wrapper.add(content, BorderLayout.NORTH);

		JScrollPane scrollPane = new JScrollPane(wrapper);
		scrollPane.setBackground(ColorScheme.DARK_GRAY_COLOR);
		scrollPane.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		scrollPane.setBorder(null);
		scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scrollPane.getVerticalScrollBar().setPreferredSize(new Dimension(8, 0));
		scrollPane.getVerticalScrollBar().setBorder(new EmptyBorder(0, 0, 0, 0));

		add(scrollPane, BorderLayout.CENTER);
		refresh();
	}

	// ── Helpers ─────────────────────────────────────────────────

	private void section(JPanel panel, String text)
	{
		JLabel label = new JLabel(text);
		label.setForeground(ACCENT);
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setBorder(new EmptyBorder(0, 0, 5, 0));
		panel.add(label);
	}

	private void row(JPanel panel, String text, JLabel valueLbl)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setOpaque(false);
		JLabel label = new JLabel(text);
		label.setForeground(MUTED);
		label.setFont(FontManager.getRunescapeSmallFont());
		valueLbl.setForeground(Color.WHITE);
		valueLbl.setFont(FontManager.getRunescapeSmallFont());
		row.add(label, BorderLayout.WEST);
		row.add(valueLbl, BorderLayout.EAST);
		panel.add(row);
	}

	private static JLabel value() { return new JLabel("—"); }

	// ── Refresh ─────────────────────────────────────────────────

	public void refresh()
	{
		SessionTracker.Snapshot s = session.snapshot(System.currentTimeMillis(), combatExperience());
		if (session.isStarted())
		{
			status.setText("TRACKING");
			status.setForeground(ACCENT);
		}
		else
		{
			status.setText("WAITING");
			status.setForeground(MUTED);
		}

		sessionTime.setText(duration(s.sessionTimeMillis));
		instanceTime.setText(duration(s.instanceTimeMillis));
		idleTime.setText(duration(s.idleTimeMillis));
		kills.setText(number(s.kills));
		deaths.setText(number(s.deaths));
		xp.setText(number(s.xp));
		xpHour.setText(number(s.xpPerHour));
		gpGained.setText(number(s.gpGained));
		gpSpent.setText(number(s.gpSpent));
		netGp.setText(number(s.netGp));
		gpHour.setText(number(s.netGpPerHour));

		dropsTitle.setText("Vorkath x " + s.kills);
		dropsTotalValue.setText(QuantityFormatter.quantityToStackSize(s.gpGained) + " gp");
		dropsTotalValue.setToolTipText("Total value: " + QuantityFormatter.formatNumber(s.gpGained) + " gp");

		if (!s.items.equals(lastRenderedItems))
		{
			lastRenderedItems = new LinkedHashMap<>(s.items);
			rebuildDropsGrid(s.items);
		}

		resourcesTotalValue.setText(QuantityFormatter.quantityToStackSize(s.resourcesCost) + " gp");
		resourcesTotalValue.setToolTipText("Total cost: " + QuantityFormatter.formatNumber(s.resourcesCost) + " gp");

		if (!s.resources.equals(lastRenderedResources))
		{
			lastRenderedResources = new ArrayList<>(s.resources);
			rebuildResourcesGrid(s.resources);
		}
	}

	private void rebuildDropsGrid(Map<Integer, Integer> items)
	{
		List<LootDisplayItem> displayItems = new ArrayList<>();
		for (Map.Entry<Integer, Integer> entry : items.entrySet())
		{
			int id = entry.getKey();
			int qty = entry.getValue();
			ItemComposition comp = itemManager.getItemComposition(id);
			String name = comp != null ? comp.getName() : "Item " + id;
			long unitPrice = itemManager.getItemPrice(id);
			displayItems.add(new LootDisplayItem(id, qty, name, unitPrice * qty));
		}
		fillGrid(dropsGridPanel, displayItems, "No drops recorded yet");
	}

	private void rebuildResourcesGrid(List<SessionTracker.ResourceUse> resources)
	{
		List<LootDisplayItem> displayItems = new ArrayList<>();
		for (SessionTracker.ResourceUse use : resources)
		{
			// Fractional uses (e.g. blowpipe scales) show as at least 1 once any have been spent
			int qty = (int) Math.max(1L, Math.round(use.qty));
			displayItems.add(new LootDisplayItem(use.itemId, qty, use.name, use.cost));
		}
		fillGrid(resourcesGridPanel, displayItems, "No resources used yet");
	}

	/** Fills a 5-column icon grid, most valuable first. Shared by the drops and resources boxes. */
	private void fillGrid(JPanel grid, List<LootDisplayItem> displayItems, String emptyText)
	{
		grid.removeAll();
		if (displayItems.isEmpty())
		{
			JPanel emptyPanel = new JPanel();
			emptyPanel.setOpaque(false);
			emptyPanel.setBorder(new EmptyBorder(8, 0, 8, 0));
			JLabel emptyLabel = new JLabel(emptyText);
			emptyLabel.setFont(FontManager.getRunescapeSmallFont());
			emptyLabel.setForeground(MUTED);
			emptyPanel.add(emptyLabel);

			grid.setLayout(new BorderLayout());
			grid.add(emptyPanel, BorderLayout.CENTER);
			grid.revalidate();
			grid.repaint();
			return;
		}

		// Sort by total price descending, then quantity, then name
		displayItems.sort((a, b) -> {
			int cmp = Long.compare(b.totalPrice, a.totalPrice);
			if (cmp != 0) return cmp;
			cmp = Integer.compare(b.qty, a.qty);
			if (cmp != 0) return cmp;
			return a.name.compareToIgnoreCase(b.name);
		});

		int total = displayItems.size();
		int rows = (int) Math.ceil((double) total / 5.0);
		grid.setLayout(new GridLayout(rows, 5, 1, 1));
		grid.setBorder(new EmptyBorder(1, 1, 1, 1));

		for (LootDisplayItem item : displayItems)
		{
			JPanel slot = new JPanel(new BorderLayout());
			slot.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			slot.setPreferredSize(new Dimension(36, 32));

			JLabel iconLabel = new JLabel();
			iconLabel.setHorizontalAlignment(SwingConstants.CENTER);
			iconLabel.setVerticalAlignment(SwingConstants.CENTER);

			String tooltip = "<html>" + item.name
				+ (item.qty > 1 ? " x " + QuantityFormatter.formatNumber(item.qty) : "")
				+ " (" + QuantityFormatter.formatNumber(item.totalPrice) + " gp)</html>";
			iconLabel.setToolTipText(tooltip);

			if (item.id > 0)
			{
				AsyncBufferedImage img = itemManager.getImage(item.id, item.qty, item.qty > 1);
				img.addTo(iconLabel);
			}
			else
			{
				iconLabel.setText(item.name.isEmpty() ? "?" : item.name.substring(0, 1));
				iconLabel.setForeground(Color.WHITE);
			}

			slot.add(iconLabel, BorderLayout.CENTER);
			grid.add(slot);
		}

		// Fill remainder of row with empty slots to preserve 5-column alignment
		int remainder = total % 5;
		if (remainder > 0)
		{
			for (int i = 0; i < 5 - remainder; i++)
			{
				JPanel emptySlot = new JPanel();
				emptySlot.setBackground(ColorScheme.DARKER_GRAY_COLOR);
				emptySlot.setPreferredSize(new Dimension(36, 32));
				grid.add(emptySlot);
			}
		}

		grid.revalidate();
		grid.repaint();
	}

	// ── Utilities ───────────────────────────────────────────────

	private long combatExperience()
	{
		long total = 0;
		for (Skill skill : new Skill[]{Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.HITPOINTS, Skill.RANGED, Skill.MAGIC})
			total += client.getSkillExperience(skill);
		return total;
	}

	private static String number(long n) { return String.format("%,d", n); }

	private static String duration(long millis)
	{
		long seconds = millis / 1000, hours = seconds / 3600, minutes = (seconds % 3600) / 60;
		return hours > 0
			? String.format("%d:%02d:%02d", hours, minutes, seconds % 60)
			: String.format("%02d:%02d", minutes, seconds % 60);
	}

	private static final class LootDisplayItem
	{
		final int id;
		final int qty;
		final String name;
		final long totalPrice;

		LootDisplayItem(int id, int qty, String name, long totalPrice)
		{
			this.id = id;
			this.qty = qty;
			this.name = name;
			this.totalPrice = totalPrice;
		}
	}
}

package com.vorkprofit.vorkath;

import com.vorkprofit.vorkath.tracker.ResourceCatalog;
import com.vorkprofit.vorkath.tracker.SessionTracker;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.Text;

/**
 * Vorkath Profit Tracker — session-based loot and cost tracker for Vorkath.
 *
 * <p>Key differences from the Zulrah version:
 * <ul>
 *   <li>Vorkath NPC IDs: 8058 (pre-fight), 8059 (main fight), 8060, 8061 (phase variants)</li>
 *   <li>Vorkath instance region IDs: 9023, 9279 (Ungael island)</li>
 *   <li>Tracks "Home Teleport" (tablet / spell) as a cost instead of Zul-andra teleports</li>
 *   <li>Panel accent colour is icy-blue rather than orange</li>
 * </ul>
 */
@PluginDescriptor(
	name        = "Vorkath Profit Tracker",
	description = "Tracks Vorkath session time, XP, loot and costs",
	tags        = {"vorkath", "gp", "profit", "tracker"},
	enabledByDefault = true
)
@Singleton
public final class VorkathPlugin extends Plugin
{
	// ── Vorkath NPC IDs ─────────────────────────────────────────────────────────
	// 8058 = sleeping/pre-fight, 8059 = main phase, 8060 = zombie-spawn phase, 8061 = enraged
	private static final int[] VORKATH_IDS = {8058, 8059, 8060, 8061};

	// ── Vorkath instance region IDs (Ungael) ────────────────────────────────────
	private static final int[] VORKATH_REGIONS = {9023, 9279};

	@Inject private Client client;
	@Inject private ClientToolbar toolbar;
	@Inject private SessionTracker session;
	@Inject private ItemManager itemManager;

	private NPC vorkath;
	private VorkathPanel panel;
	private NavigationButton button;
	private boolean deathRecorded;
	private WorldPoint lootOrigin;
	private int pendingItemId = -1;
	private long pendingItemClickTime;
	private Map<Integer, Integer> lastInventory = new HashMap<>();
	private final Map<Integer, Long> droppedItems = new HashMap<>();

	// ── Resource tracking (ammo, runes, teleport charges, Zulrah's scales) ───────
	/** Rune pouch varbits: rune type + amount for each of the (up to) four slots. */
	private static final int[] POUCH_RUNE_VARBITS   = {29, 1622, 1623, 14285};
	private static final int[] POUCH_AMOUNT_VARBITS = {1624, 1625, 1626, 14286};
	/** Cache enum that maps a rune-pouch rune type to its item id. */
	private static final int RUNEPOUCH_RUNE_ENUM = 982;

	/** Toxic blowpipe: 1/3 chance to save the scale on each shot -> 2/3 scale per shot on average (tracked in thirds). */
	private static final int BLOWPIPE_SCALE_THIRDS_PER_SHOT = 2;
	/** Serpentine-family helms burn 10 scales on entering combat and 10 more every 90 ticks of combat. */
	private static final int HELM_SCALES_PER_BURN = 10;
	private static final int HELM_BURN_PERIOD_TICKS = 90;
	/** Ticks without dealing / taking a hit before we consider the player out of combat. */
	private static final int COMBAT_TIMEOUT_TICKS = 16;
	private static final Pattern BLOWPIPE_CHECK = Pattern.compile("Darts:\\s*(.+?)\\s+x\\s*([\\d,]+)", Pattern.CASE_INSENSITIVE);

	private int tick;
	private int lastInstanceTick = -1000;
	private int lastCombatTick = -1000;
	private int lastShotTick = -1000;
	private long lastDeathMs;
	private long lastBankEventMs;
	private boolean baselineReady;
	private Item[] inventoryItems = new Item[0];
	private Item[] equipmentItems = new Item[0];
	private final Set<Integer> ammoIds = new HashSet<>();
	private final Map<Integer, String> nameCache = new HashMap<>();
	private Map<Integer, Integer> lastTracked = new HashMap<>();
	private Map<String, Integer> lastCharges = new HashMap<>();
	private final Map<String, Long> costPerCharge = new HashMap<>();
	private final Map<String, Integer> chargeIconId = new HashMap<>();
	private boolean helmInCombat;
	private int helmCombatStartTick;
	private int blowpipeScaleThirds;
	private int dartItemId = ResourceCatalog.DRAGON_DART_ID;

	// ── Lifecycle ────────────────────────────────────────────────────────────────

	@Override
	protected void startUp()
	{
		panel = new VorkathPanel(session, client, itemManager);
		button = NavigationButton.builder()
			.tooltip("Vorkath Profit Tracker")
			.priority(8)
			.icon(VorkathIcon.create())
			.panel(panel)
			.build();
		toolbar.addNavigation(button);
	}

	@Override
	protected void shutDown()
	{
		if (button != null) toolbar.removeNavigation(button);
		vorkath = null;
		panel = null;
		droppedItems.clear();
		resetResourceBaseline();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		// Containers are re-sent on login / world hop, so don't diff across those. LOADING is
		// deliberately ignored: teleporting out of the instance loads a new region.
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING || state == GameState.CONNECTION_LOST)
		{
			resetResourceBaseline();
		}
	}

	private void resetResourceBaseline()
	{
		baselineReady = false;
		lastTracked = new HashMap<>();
		lastCharges = new HashMap<>();
		inventoryItems = new Item[0];
		equipmentItems = new Item[0];
		helmInCombat = false;
	}

	// ── Game tick: instance detection & panel refresh ─────────────────────────

	@Subscribe
	public void onGameTick(GameTick event)
	{
		long now = System.currentTimeMillis();
		boolean inInstance = isInVorkathInstance();
		tick++;

		// Start session when the player climbs over the rock into the instance
		if (!session.isStarted() && inInstance)
		{
			session.start(now, combatExperience());
		}

		session.tickTimers(now, inInstance);
		trackResources(now, inInstance);

		if (vorkath == null)
		{
			for (NPC npc : client.getNpcs())
			{
				if (isVorkath(npc))
				{
					vorkath = npc;
					deathRecorded = false;
					break;
				}
			}
		}

		if (panel != null)
		{
			panel.refresh();
		}
	}

	// ── NPC tracking ─────────────────────────────────────────────────────────

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		if (isVorkath(event.getNpc())) { vorkath = event.getNpc(); deathRecorded = false; }
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		if (event.getNpc() == vorkath) { vorkath = null; deathRecorded = false; }
	}

	// ── Kill / death recording ─────────────────────────────────────────────────

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (event.getActor() == vorkath && !deathRecorded)
		{
			deathRecorded = true;
			lootOrigin = vorkath.getWorldLocation();
			session.recordKill(System.currentTimeMillis());
		}
		else if (event.getActor() == client.getLocalPlayer())
		{
			lastDeathMs = System.currentTimeMillis();
			session.recordDeath();
		}
	}

	// ── Combat hooks used for blowpipe shots / helm scale burn ───────────────────

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		Actor actor = event.getActor();
		if (actor == null || event.getHitsplat() == null) return;

		if (actor == client.getLocalPlayer())
		{
			lastCombatTick = tick;
			return;
		}

		if (actor instanceof NPC && isVorkath((NPC) actor) && event.getHitsplat().isMine())
		{
			lastCombatTick = tick;
			// One shot per tick at most, so a vengeance proc on the same tick is not a second shot.
			if (tick != lastShotTick && session.isStarted() && isWeaponEquipped(ResourceCatalog::isBlowpipe))
			{
				lastShotTick = tick;
				recordBlowpipeShot();
			}
		}
	}

	/** Learns which darts are loaded when the player uses the blowpipe's "Check" option. */
	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE || event.getMessage() == null) return;

		Matcher matcher = BLOWPIPE_CHECK.matcher(Text.removeTags(event.getMessage()));
		if (!matcher.find()) return;

		String dartName = matcher.group(1).trim();
		for (var result : itemManager.search(dartName))
		{
			if (result.getName() != null && result.getName().equalsIgnoreCase(dartName))
			{
				dartItemId = result.getId();
				return;
			}
		}
	}

	// ── Loot tracking ─────────────────────────────────────────────────────────

	@Subscribe
	public void onItemSpawned(ItemSpawned event)
	{
		WorldPoint location = event.getTile().getWorldLocation();
		if (!session.acceptsLoot(System.currentTimeMillis())
			|| lootOrigin == null
			|| location.distanceTo2D(lootOrigin) > 8) return;

		TileItem item = event.getItem();
		Long droppedTime = droppedItems.get(item.getId());
		if (droppedTime != null && System.currentTimeMillis() - droppedTime < 3000L)
		{
			return;
		}

		int id = item.getId();
		int quantity = item.getQuantity();
		long price = (long) quantity * itemManager.getItemPrice(id);
		session.recordLoot(id, quantity, price);
	}

	// ── Consumable / cost tracking ─────────────────────────────────────────────

	/**
	 * Intercepts clicks on consumables and home teleport tablets/spells so we can
	 * correlate them with the subsequent inventory-change event.
	 *
	 * <p>For Vorkath we track:
	 * <ul>
	 *   <li>Food (eat)</li>
	 *   <li>Potions (drink)</li>
	 *   <li>Teleport tablets / runes (teleport / break) — covers "Home Teleport" tablets
	 *       and POH teleport tablets used to return after a kill</li>
	 *   <li>Prayer flick items (read) e.g. Dragonfire shields are not consumables but
	 *       scrolls/prayer books with a "read" action would be counted</li>
	 * </ul>
	 */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		int itemId = event.getItemId();
		if (itemId <= 0) return;

		ItemComposition def = itemManager.getItemComposition(itemId);
		if (def == null || def.getName() == null) return;

		String name   = def.getName().toLowerCase(Locale.ROOT);
		String option = event.getMenuOption() == null ? "" : event.getMenuOption().toLowerCase(Locale.ROOT);

		// Never count depositing/storing items as a cost
		if (option.startsWith("deposit") || option.startsWith("store")) return;

		if ("drop".equals(option))
		{
			droppedItems.put(itemId, System.currentTimeMillis());
			return;
		}

		boolean trackedAction = "eat".equals(option)
			|| "drink".equals(option)
			|| "teleport".equals(option)
			|| "break".equals(option)
			|| "read".equals(option);

		// Explicitly catch house teleports, home teleports, and Rellekka teleports by name
		// (e.g. Teleport to house tablet, House teleport tablet, Construction cape, Rellekka teleport tablet)
		if (!trackedAction && (name.contains("teleport to house")
			|| name.contains("house teleport")
			|| name.contains("home teleport")
			|| name.contains("rellekka teleport")
			|| name.contains("construction cape")))
		{
			trackedAction = true;
		}

		// Fall back: check the item's own inventory actions for eat/drink/teleport/break
		if (!trackedAction && def.getInventoryActions() != null)
			for (String action : def.getInventoryActions())
				if (action != null && action.equalsIgnoreCase(option)
					&& ("eat".equalsIgnoreCase(action) || "drink".equalsIgnoreCase(action)
					|| "teleport".equalsIgnoreCase(action) || "break".equalsIgnoreCase(action)
					|| "read".equalsIgnoreCase(action)))
				{
					trackedAction = true;
					break;
				}

		if (trackedAction) { pendingItemId = itemId; pendingItemClickTime = System.currentTimeMillis(); }
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int containerId = event.getContainerId();
		if (containerId == InventoryID.BANK.getId())
		{
			// Deposits / withdrawals change charge totals; remember so we can ignore them.
			lastBankEventMs = System.currentTimeMillis();
			return;
		}
		if (containerId == InventoryID.EQUIPMENT.getId())
		{
			equipmentItems = event.getItemContainer() == null ? new Item[0] : event.getItemContainer().getItems().clone();
			return;
		}
		if (containerId != InventoryID.INVENTORY.getId()
			|| event.getItemContainer() == null) return;

		inventoryItems = event.getItemContainer().getItems().clone();

		Map<Integer, Integer> current = new HashMap<>();
		for (Item item : event.getItemContainer().getItems())
			if (item != null && item.getId() > 0)
				current.put(item.getId(), current.getOrDefault(item.getId(), 0) + item.getQuantity());

		if (!lastInventory.isEmpty() && System.currentTimeMillis() - pendingItemClickTime < 3000)
		{
			for (Map.Entry<Integer, Integer> entry : lastInventory.entrySet())
			{
				int id = entry.getKey();
				int consumed = entry.getValue() - current.getOrDefault(id, 0);
				if (id == pendingItemId && consumed > 0)
				{
					ItemComposition def = itemManager.getItemComposition(id);
					if (def != null && def.getName() != null
						&& isTrackedConsumable(def, def.getName().toLowerCase(Locale.ROOT)))
					{
						String lowerName = def.getName().toLowerCase(Locale.ROOT);
						long unitCost = calculateItemCost(lowerName, itemManager.getItemPrice(id));
						// Grouped by base name so "Super restore (4)" and "(3)" share one slot (qty = doses / items)
						session.recordResource(ResourceCatalog.baseName(lowerName),
							ResourceCatalog.baseName(def.getName()), id, consumed, unitCost * consumed);
					}
					pendingItemId = -1;
					break;
				}
			}
		}
		lastInventory = current;
	}

	// ── Private helpers ───────────────────────────────────────────────────────

	/**
	 * Returns true when the player is inside the Vorkath (Ungael) instanced region.
	 * We check both {@code isInInstancedRegion()} and the specific region IDs to avoid
	 * false positives in other instanced content.
	 */
	private boolean isInVorkathInstance()
	{
		if (!client.isInInstancedRegion()) return false;
		int[] regions = client.getMapRegions();
		if (regions == null) return false;
		for (int region : regions)
			for (int vorkRegion : VORKATH_REGIONS)
				if (region == vorkRegion) return true;
		return false;
	}

	private boolean isTrackedConsumable(ItemComposition def, String name)
	{
		// Rings of dueling, glories etc. lose a charge rather than an item: handled by trackTeleportCharges()
		if (ResourceCatalog.parseChargedTeleport(name) != null) return false;
		// Potion doses, teleport tablets and home/house teleport items
		if (name.contains("teleport to house")
			|| name.contains("house teleport")
			|| name.contains("home teleport")
			|| name.contains("rellekka teleport")
			|| name.matches(".*\\([1-4]\\)$")) return true;
		String[] actions = def.getInventoryActions();
		if (actions != null)
			for (String action : actions)
				if ("eat".equalsIgnoreCase(action) || "drink".equalsIgnoreCase(action)
					|| "break".equalsIgnoreCase(action) || "teleport".equalsIgnoreCase(action)) return true;
		return false;
	}

	/**
	 * Converts a full-item price to a per-use (per-dose) cost.
	 * Teleport tablets are single-use; potions are divided by their current dose count.
	 */
	private long calculateItemCost(String name, long price)
	{
		// Single-use teleport items — charge the full GE price
		if (name.contains("teleport to house")
			|| name.contains("house teleport")
			|| name.contains("home teleport")
			|| name.contains("rellekka teleport")) return price;
		// Potions: "(4)" "(3)" "(2)" "(1)" — pro-rate by dose
		Matcher matcher = Pattern.compile(".*\\((\\d)\\)$").matcher(name);
		if (matcher.matches())
		{
			int doses = Integer.parseInt(matcher.group(1));
			if (doses > 0) return Math.max(1, price / doses);
		}
		return price;
	}

	// ── Resources used: ammo, runes, teleport charges, Zulrah's scales ─────────

	/**
	 * Runs once per game tick. Compares what the player owns (inventory + equipment + rune pouch)
	 * with the previous tick and turns decreases into "resources used". The baseline is refreshed
	 * every tick so banking, equipping, login etc. never register as spending.
	 */
	private void trackResources(long now, boolean inInstance)
	{
		if (inInstance) lastInstanceTick = tick;
		boolean nearInstance = inInstance || tick - lastInstanceTick <= 10;
		boolean ignore = !baselineReady || !session.isStarted() || now - lastDeathMs < 10_000L;

		Map<Integer, Integer> owned = new HashMap<>();
		addItems(owned, inventoryItems);
		addItems(owned, equipmentItems);
		learnAmmo();

		trackAmmoAndRunes(now, owned, ignore || !nearInstance);
		trackTeleportCharges(now, owned, ignore || now - lastBankEventMs < 3000L);
		trackScaleHelm(inInstance && session.isStarted());
		baselineReady = true;
	}

	private static void addItems(Map<Integer, Integer> into, Item[] items)
	{
		if (items == null) return;
		for (Item item : items)
			if (item != null && item.getId() > 0 && item.getQuantity() > 0)
				into.merge(item.getId(), item.getQuantity(), Integer::sum);
	}

	/** Remembers every ammo / thrown weapon id the player has had equipped this session. */
	private void learnAmmo()
	{
		Item ammo = slot(equipmentItems, EquipmentInventorySlot.AMMO.getSlotIdx());
		if (ammo != null && ammo.getId() > 0) ammoIds.add(ammo.getId());

		Item weapon = slot(equipmentItems, EquipmentInventorySlot.WEAPON.getSlotIdx());
		if (weapon != null && weapon.getId() > 0 && ResourceCatalog.isThrownWeapon(lowerName(weapon.getId())))
			ammoIds.add(weapon.getId());
	}

	private void trackAmmoAndRunes(long now, Map<Integer, Integer> owned, boolean ignore)
	{
		Map<Integer, Integer> tracked = new HashMap<>();
		boolean hasPouch = false;
		for (Map.Entry<Integer, Integer> entry : owned.entrySet())
		{
			int id = entry.getKey();
			String name = lowerName(id);
			if (ammoIds.contains(id) || ResourceCatalog.isRune(name)) tracked.put(id, entry.getValue());
			if (ResourceCatalog.isRunePouch(name)) hasPouch = true;
		}
		if (hasPouch) addPouchRunes(tracked);

		if (!ignore)
		{
			for (Map.Entry<Integer, Integer> entry : lastTracked.entrySet())
			{
				int id = entry.getKey();
				int used = entry.getValue() - tracked.getOrDefault(id, 0);
				if (used <= 0) continue;
				Long dropped = droppedItems.get(id);
				if (dropped != null && now - dropped < 3000L) continue; // player dropped it, not used
				session.recordResource(lowerName(id), itemName(id), id, used, itemManager.getItemPrice(id) * (long) used);
			}
		}
		lastTracked = tracked;
	}

	/** Adds the contents of the rune pouch (or divine rune pouch) to {@code into}. */
	private void addPouchRunes(Map<Integer, Integer> into)
	{
		try
		{
			EnumComposition runeEnum = client.getEnum(RUNEPOUCH_RUNE_ENUM);
			if (runeEnum == null) return;
			for (int i = 0; i < POUCH_RUNE_VARBITS.length; i++)
			{
				int type = client.getVarbitValue(POUCH_RUNE_VARBITS[i]);
				int amount = client.getVarbitValue(POUCH_AMOUNT_VARBITS[i]);
				if (type <= 0 || amount <= 0) continue;
				int runeId = runeEnum.getIntValue(type);
				if (runeId > 0) into.merge(runeId, amount, Integer::sum);
			}
		}
		catch (RuntimeException ignored)
		{
			// Rune pouch data unavailable this tick; skip rather than risk a false "used" reading.
		}
	}

	/**
	 * Charged teleport jewellery (dueling rings, glories, skills necklaces...) loses a charge per
	 * teleport instead of an item, so we compare the total charges the player holds per family.
	 */
	private void trackTeleportCharges(long now, Map<Integer, Integer> owned, boolean ignore)
	{
		Map<String, Integer> charges = new HashMap<>();
		Map<String, Integer> bestCharges = new HashMap<>();
		for (Map.Entry<Integer, Integer> entry : owned.entrySet())
		{
			int id = entry.getKey();
			ResourceCatalog.Charged charged = ResourceCatalog.parseChargedTeleport(lowerName(id));
			if (charged == null) continue;

			charges.merge(charged.family, charged.charges * entry.getValue(), Integer::sum);
			if (charged.charges > bestCharges.getOrDefault(charged.family, 0))
			{
				// Price one charge from the fullest item held (most accurate GE price)
				bestCharges.put(charged.family, charged.charges);
				costPerCharge.put(charged.family, (long) itemManager.getItemPrice(id) / charged.charges);
				chargeIconId.put(charged.family, id);
			}
			chargeIconId.putIfAbsent(charged.family, id);
		}

		// A real teleport removes exactly one charge. Bigger drops are trades, deposits, alching, etc.
		if (!ignore && !droppedRecently(now))
		{
			for (Map.Entry<String, Integer> entry : lastCharges.entrySet())
			{
				String family = entry.getKey();
				int used = entry.getValue() - charges.getOrDefault(family, 0);
				if (used != 1) continue;
				String display = Character.toUpperCase(family.charAt(0)) + family.substring(1);
				session.recordResource(family, display, chargeIconId.getOrDefault(family, -1),
					used, costPerCharge.getOrDefault(family, 0L) * used);
			}
		}
		lastCharges = charges;
	}

	private boolean droppedRecently(long now)
	{
		for (long time : droppedItems.values())
			if (now - time < 3000L) return true;
		return false;
	}

	/** Serpentine / magma / tanzanite helm: scales burn on entering combat and every 90 combat ticks. */
	private void trackScaleHelm(boolean active)
	{
		if (!active
			|| !isWearing(EquipmentInventorySlot.HEAD.getSlotIdx(), ResourceCatalog::isScaleHelm)
			|| tick - lastCombatTick > COMBAT_TIMEOUT_TICKS)
		{
			helmInCombat = false;
			return;
		}

		if (!helmInCombat)
		{
			helmInCombat = true;
			helmCombatStartTick = tick;
			recordScales(HELM_SCALES_PER_BURN);
		}
		else if (tick - helmCombatStartTick >= HELM_BURN_PERIOD_TICKS)
		{
			helmCombatStartTick += HELM_BURN_PERIOD_TICKS;
			recordScales(HELM_SCALES_PER_BURN);
		}
	}

	/** One blowpipe shot = one dart plus on average 2/3 of a Zulrah's scale. */
	private void recordBlowpipeShot()
	{
		session.recordResource(lowerName(dartItemId), itemName(dartItemId), dartItemId,
			1, itemManager.getItemPrice(dartItemId));

		blowpipeScaleThirds += BLOWPIPE_SCALE_THIRDS_PER_SHOT;
		int whole = blowpipeScaleThirds / 3;
		if (whole > 0)
		{
			blowpipeScaleThirds -= whole * 3;
			recordScales(whole);
		}
	}

	private void recordScales(int amount)
	{
		session.recordResource("zulrah's scales", "Zulrah's scales", ResourceCatalog.ZULRAHS_SCALES_ID,
			amount, itemManager.getItemPrice(ResourceCatalog.ZULRAHS_SCALES_ID) * (long) amount);
	}

	private boolean isWeaponEquipped(java.util.function.Predicate<String> test)
	{
		return isWearing(EquipmentInventorySlot.WEAPON.getSlotIdx(), test);
	}

	private boolean isWearing(int slotIdx, java.util.function.Predicate<String> test)
	{
		Item item = slot(equipmentItems, slotIdx);
		return item != null && item.getId() > 0 && test.test(lowerName(item.getId()));
	}

	private static Item slot(Item[] items, int idx)
	{
		return items != null && idx >= 0 && idx < items.length ? items[idx] : null;
	}

	private String itemName(int id)
	{
		return nameCache.computeIfAbsent(id, key -> {
			ItemComposition def = itemManager.getItemComposition(key);
			return def == null || def.getName() == null ? "" : def.getName();
		});
	}

	private String lowerName(int id)
	{
		return itemName(id).toLowerCase(Locale.ROOT);
	}

	private boolean isVorkath(NPC npc)
	{
		if (npc == null) return false;
		int id = npc.getId();
		for (int vid : VORKATH_IDS)
			if (id == vid) return true;
		return false;
	}

	private long combatExperience()
	{
		long total = 0;
		for (Skill skill : new Skill[]{Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.HITPOINTS, Skill.RANGED, Skill.MAGIC})
			total += client.getSkillExperience(skill);
		return total;
	}
}

package com.vorkprofit.vorkath.tracker;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Pure (RuneLite-free) name-matching helpers used to decide what counts as a "resource used".
 * Everything here works on lower-case item names so it can be unit tested without a client.
 */
public final class ResourceCatalog
{
	/** Item id of Zulrah's scales (used to price helm / blowpipe scale usage). */
	public static final int ZULRAHS_SCALES_ID = 12934;
	/** Item id of the dragon dart (default blowpipe ammo until the player checks the blowpipe). */
	public static final int DRAGON_DART_ID = 11230;

	/** Matches "(4)", "(t4)" and " (8)" charge/dose suffixes. */
	private static final Pattern CHARGE_SUFFIX = Pattern.compile("^(.*?)\\s*\\((?:t)?(\\d+)\\)$");

	/** Charged teleport jewellery / items: each teleport removes one charge. */
	private static final Set<String> TELEPORT_FAMILIES = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		"ring of dueling",
		"amulet of glory",
		"amulet of glory (t)",
		"games necklace",
		"skills necklace",
		"combat bracelet",
		"necklace of passage",
		"ring of wealth",
		"ring of wealth (i)",
		"burning amulet",
		"digsite pendant",
		"slayer ring",
		"ring of returning",
		"enchanted lyre"
	)));

	private ResourceCatalog()
	{
	}

	/** A charged teleport item parsed from its name. */
	public static final class Charged
	{
		public final String family;
		public final int charges;

		Charged(String family, int charges)
		{
			this.family = family;
			this.charges = charges;
		}
	}

	/**
	 * Parses e.g. "ring of dueling(5)" into family "ring of dueling" with 5 charges. The uncharged
	 * variant (no suffix, e.g. "amulet of glory") is part of the family with 0 charges.
	 * Returns null when the item is not charged teleport jewellery.
	 */
	public static Charged parseChargedTeleport(String lowerName)
	{
		if (lowerName == null)
		{
			return null;
		}
		String name = lowerName.trim();
		if (TELEPORT_FAMILIES.contains(name))
		{
			return new Charged(name, 0);
		}
		Matcher m = CHARGE_SUFFIX.matcher(name);
		if (m.matches() && TELEPORT_FAMILIES.contains(m.group(1)))
		{
			return new Charged(m.group(1), Integer.parseInt(m.group(2)));
		}
		return null;
	}

	/** Strips a trailing "(4)" dose / charge marker, e.g. "super restore(3)" -> "super restore". */
	public static String baseName(String lowerName)
	{
		if (lowerName == null)
		{
			return "";
		}
		Matcher m = CHARGE_SUFFIX.matcher(lowerName.trim());
		return m.matches() ? m.group(1) : lowerName.trim();
	}

	public static boolean isRune(String lowerName)
	{
		return lowerName != null && lowerName.endsWith(" rune");
	}

	public static boolean isRunePouch(String lowerName)
	{
		return lowerName != null && lowerName.contains("rune pouch");
	}

	/** Thrown weapons sit in the weapon slot and are used up like ammo. */
	public static boolean isThrownWeapon(String lowerName)
	{
		if (lowerName == null || lowerName.contains("blowpipe") || lowerName.contains("tip"))
		{
			return false;
		}
		return lowerName.contains("dart")
			|| lowerName.contains("throwing knife")
			|| lowerName.endsWith(" knife")
			|| lowerName.contains("throwing axe")
			|| lowerName.contains("thrownaxe")
			|| lowerName.contains("chinchompa")
			|| lowerName.contains("javelin");
	}

	public static boolean isBlowpipe(String lowerName)
	{
		return lowerName != null && lowerName.contains("blowpipe") && !lowerName.contains("(empty)");
	}

	/** Serpentine / magma / tanzanite helm that is charged with Zulrah's scales. */
	public static boolean isScaleHelm(String lowerName)
	{
		if (lowerName == null || lowerName.contains("uncharged"))
		{
			return false;
		}
		return lowerName.equals("serpentine helm")
			|| lowerName.equals("magma helm")
			|| lowerName.equals("tanzanite helm");
	}
}

package com.vorkprofit.vorkath.tracker;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/**
 * Session-only kill, death, session time, instance time, idle time, experience, loot and consumable/reclaim cost
 * accounting for Vorkath. Values are reset when the plugin restarts or the user clicks Reset.
 */
public final class SessionTracker
{
	private static final long LOOT_WINDOW_MILLIS = 30_000L;
	/** RuneScape death-reclaim cost at Vorkath (gravestones cost ~100k). */
	private static final long DEATH_RECLAIM_COST = 100_000L;

	private long startedAt = -1L;
	private long startingXp;
	private int kills;
	private int deaths;
	private long sessionTimeMillis;
	private long instanceTimeMillis;
	private long timerLastTick = -1L;
	private long gpGained;
	private long gpSpent;
	private long lootWindowEnds;
	private final Map<Integer, Integer> sessionItems = new LinkedHashMap<>();
	/** Everything consumed this session (supplies, ammo, runes, teleport charges, scales), keyed by name. */
	private final Map<String, ResourceUse> resources = new LinkedHashMap<>();

	public boolean isStarted()
	{
		return startedAt >= 0L;
	}

	public void startIfNeeded(long now, long overallXp)
	{
		if (startedAt < 0L)
		{
			start(now, overallXp);
		}
	}

	public void start(long now, long overallXp)
	{
		startedAt = now;
		startingXp = overallXp;
		timerLastTick = now;
	}

	public void tickTimers(long now, boolean inInstance)
	{
		if (startedAt < 0L)
		{
			return;
		}

		if (timerLastTick >= 0L)
		{
			long delta = now - timerLastTick;
			if (delta > 0L && delta < 10_000L)
			{
				sessionTimeMillis += delta;
				if (inInstance)
				{
					instanceTimeMillis += delta;
				}
			}
		}
		timerLastTick = now;
	}

	public void tickInstanceTimer(long now, boolean inInstance)
	{
		tickTimers(now, inInstance);
	}

	public void resetSession(long now, long overallXp)
	{
		startedAt = -1L;
		startingXp = overallXp;
		kills = 0;
		deaths = 0;
		sessionTimeMillis = 0L;
		instanceTimeMillis = 0L;
		timerLastTick = -1L;
		gpGained = 0L;
		gpSpent = 0L;
		lootWindowEnds = 0L;
		sessionItems.clear();
		resources.clear();
	}

	public void recordKill(long now)
	{
		kills++;
		lootWindowEnds = now + LOOT_WINDOW_MILLIS;
	}

	public void recordDeath()
	{
		deaths++;
		gpSpent += DEATH_RECLAIM_COST;
	}

	public boolean acceptsLoot(long now)
	{
		return now <= lootWindowEnds;
	}

	public void recordLoot(long value)
	{
		recordLoot(-1, 0, value);
	}

	public void recordLoot(int itemId, int quantity, long value)
	{
		if (value > 0L)
		{
			gpGained += value;
		}
		if (itemId > 0 && quantity > 0)
		{
			sessionItems.put(itemId, sessionItems.getOrDefault(itemId, 0) + quantity);
		}
	}

	public void recordItemSpent(long itemPrice)
	{
		if (itemPrice > 0L)
		{
			gpSpent += itemPrice;
		}
	}

	/**
	 * Records a consumed resource (food, potion dose, arrow, rune, teleport charge, Zulrah's scale...).
	 * The cost is added to GP spent and the quantity shows up in the "Resources used" box.
	 *
	 * @param key    stable grouping key (lower-case base name, e.g. "super restore")
	 * @param name   display name
	 * @param itemId item whose icon represents the resource
	 * @param qty    units used (doses, arrows, charges...)
	 * @param cost   total gp cost of those units
	 */
	public void recordResource(String key, String name, int itemId, double qty, long cost)
	{
		if (key == null || (qty <= 0d && cost <= 0L))
		{
			return;
		}
		long safeCost = Math.max(0L, cost);
		gpSpent += safeCost;
		ResourceUse old = resources.get(key);
		resources.put(key, old == null
			? new ResourceUse(name, itemId, qty, safeCost)
			: new ResourceUse(old.name, old.itemId, old.qty + qty, old.cost + safeCost));
	}

	public Snapshot snapshot(long now, long overallXp)
	{
		if (startedAt < 0L)
		{
			return new Snapshot(
				0, 0, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 0L,
				Collections.emptyMap(), Collections.emptyList(), 0L
			);
		}
		long resourcesCost = 0L;
		for (ResourceUse use : resources.values())
		{
			resourcesCost += use.cost;
		}

		long activeTime = Math.max(1L, instanceTimeMillis);
		long idleTime = Math.max(0L, sessionTimeMillis - instanceTimeMillis);
		long xp = Math.max(0L, overallXp - startingXp);
		long netGp = gpGained - gpSpent;
		return new Snapshot(
			kills,
			deaths,
			sessionTimeMillis,
			instanceTimeMillis,
			idleTime,
			xp,
			gpGained,
			gpSpent,
			netGp,
			kills * 3_600_000L / activeTime,
			xp * 3_600_000L / activeTime,
			gpGained * 3_600_000L / activeTime,
			netGp * 3_600_000L / activeTime,
			Collections.unmodifiableMap(new LinkedHashMap<>(sessionItems)),
			Collections.unmodifiableList(new ArrayList<>(resources.values())),
			resourcesCost
		);
	}

	/** One line of the "Resources used" box. Immutable. */
	public static final class ResourceUse
	{
		public final String name;
		public final int itemId;
		public final double qty;
		public final long cost;

		ResourceUse(String name, int itemId, double qty, long cost)
		{
			this.name = name;
			this.itemId = itemId;
			this.qty = qty;
			this.cost = cost;
		}

		@Override
		public boolean equals(Object o)
		{
			if (this == o) return true;
			if (!(o instanceof ResourceUse)) return false;
			ResourceUse other = (ResourceUse) o;
			return itemId == other.itemId && cost == other.cost
				&& Double.compare(qty, other.qty) == 0 && Objects.equals(name, other.name);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(name, itemId, qty, cost);
		}
	}

	public static final class Snapshot
	{
		public final int kills;
		public final int deaths;
		public final long sessionTimeMillis;
		public final long instanceTimeMillis;
		public final long idleTimeMillis;
		public final long xp;
		public final long gpGained;
		public final long gpSpent;
		public final long netGp;
		public final long killsPerHour;
		public final long xpPerHour;
		public final long gpPerHour;
		public final long netGpPerHour;
		public final Map<Integer, Integer> items;
		/** Everything consumed this session. Already included in {@link #gpSpent}. */
		public final List<ResourceUse> resources;
		/** Total gp value of {@link #resources}. */
		public final long resourcesCost;

		Snapshot(
			int kills,
			int deaths,
			long sessionTimeMillis,
			long instanceTimeMillis,
			long idleTimeMillis,
			long xp,
			long gpGained,
			long gpSpent,
			long netGp,
			long killsPerHour,
			long xpPerHour,
			long gpPerHour,
			long netGpPerHour,
			Map<Integer, Integer> items,
			List<ResourceUse> resources,
			long resourcesCost
		)
		{
			this.kills = kills;
			this.deaths = deaths;
			this.sessionTimeMillis = sessionTimeMillis;
			this.instanceTimeMillis = instanceTimeMillis;
			this.idleTimeMillis = idleTimeMillis;
			this.xp = xp;
			this.gpGained = gpGained;
			this.gpSpent = gpSpent;
			this.netGp = netGp;
			this.killsPerHour = killsPerHour;
			this.xpPerHour = xpPerHour;
			this.gpPerHour = gpPerHour;
			this.netGpPerHour = netGpPerHour;
			this.items = items;
			this.resources = resources;
			this.resourcesCost = resourcesCost;
		}
	}
}

